CREATE TABLE identity_user_credentials (id varchar(64) PRIMARY KEY,user_id varchar(64) NOT NULL,password_hash text NOT NULL,failed_attempts bigint NOT NULL DEFAULT 0,locked_until timestamp(6) NULL,password_changed_at timestamp(6) NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY identity_user_credentials_user_unique(user_id));
CREATE TABLE identity_sessions (id varchar(64) PRIMARY KEY,user_id varchar(64) NOT NULL,refresh_token_hash varchar(64) NOT NULL,previous_refresh_token_hash varchar(64) NOT NULL DEFAULT '',expires_at timestamp(6) NOT NULL,last_seen_at timestamp(6) NOT NULL,revoked_at timestamp(6) NULL,revoke_reason text NOT NULL,client_ip text NOT NULL,user_agent text NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY identity_sessions_refresh_unique(refresh_token_hash),KEY identity_sessions_user_idx(user_id,expires_at));
